    #[test]
    fn onepassword_stores_and_reads_api_credentials() {
        const CHILD_ROOT: &str = "COOP_TEST_ONEPASSWORD_ROOT";
        if let Some(root) = std::env::var_os(CHILD_ROOT) {
            for (service, name) in [
                (SERVICE, "owner-repo"),
                (ANTHROPIC_SERVICE, "anthropic"),
                (OPENAI_SERVICE, "openai"),
            ] {
                // Leave the legacy command unchanged, as happens when saving the
                // replacement command to config.toml or proxy.json fails.
                let saved = CmdToken::OnePassword {
                    title: format!("{service} ({name})"),
                    field: OnePasswordField::Password,
                }
                .to_string();
                for token in ["first-api-token", "rotated-api-token"] {
                    let stored = store_secret(
                        Backend::OnePassword,
                        service,
                        &AccountName::new(name).unwrap(),
                        token,
                        Path::new(&root),
                    )
                    .unwrap();
                    assert_eq!(CmdToken::parse(&stored.to_string()), Some(stored.clone()));
                    assert!(matches!(
                        stored,
                        CmdToken::OnePassword {
                            field: OnePasswordField::Credential,
                            ..
                        }
                    ));
                    for command in [&saved, &stored.to_string()] {
                        assert_eq!(crate::config::resolve_cmd_value(command).unwrap(), token);
                    }
                }
            }
            return;
        }

        // Change PATH only in a child so parallel tests keep their real tools.
        let root = tempfile::tempdir().unwrap();
        std::os::unix::fs::symlink("/bin/sh", root.path().join("sh")).unwrap();
        let op = root.path().join("op");
        std::fs::write(
            &op,
            r#"#!/bin/sh
[ "$1" = item ] || exit 1
case "$2" in
    delete)
        # Archiving removes both fields from the active item.
        printf '' > "$COOP_TEST_ONEPASSWORD_ROOT/password"
        printf '' > "$COOP_TEST_ONEPASSWORD_ROOT/credential"
        ;;
    create)
        [ "$#" = 6 ] || exit 2
        [ "$3" = '--category=API Credential' ] || exit 3
        case "$5" in credential=*) ;; *) exit 4 ;; esac
        case "$6" in 'password[password]='*) ;; *) exit 4 ;; esac
        printf '%s\n' "${5#*=}" > "$COOP_TEST_ONEPASSWORD_ROOT/credential"
        printf '%s\n' "${6#*=}" > "$COOP_TEST_ONEPASSWORD_ROOT/password"
        printf '%s\n' "${4#--title=}" > "$COOP_TEST_ONEPASSWORD_ROOT/title"
        printf '%s\n' "$4" >> "$COOP_TEST_ONEPASSWORD_ROOT/created"
        ;;
    get)
        [ "$#" = 6 ] || exit 5
        [ "$4" = --fields ] && [ "$6" = --reveal ] || exit 6
        read -r title < "$COOP_TEST_ONEPASSWORD_ROOT/title"
        [ "$3" = "$title" ] || exit 6
        case "$5" in password|credential) ;; *) exit 6 ;; esac
        read -r token < "$COOP_TEST_ONEPASSWORD_ROOT/$5" || exit 6
        printf '%s\n' "$token"
        ;;
    *) exit 7 ;;
esac
"#,
        )
        .unwrap();
        std::fs::set_permissions(&op, std::fs::Permissions::from_mode(0o755)).unwrap();
        let output = Command::new(std::env::current_exe().unwrap())
            .args([
                "--exact",
                "secret_store::tests::onepassword_stores_and_reads_api_credentials",
            ])
            .env(CHILD_ROOT, root.path())
            .env("PATH", root.path())
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "stdout={} stderr={}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        assert_eq!(
            std::fs::read_to_string(root.path().join("created")).unwrap(),
            "--title=coop-github-pat (owner-repo)\n\
             --title=coop-github-pat (owner-repo)\n\
             --title=coop-anthropic (anthropic)\n\
             --title=coop-anthropic (anthropic)\n\
             --title=coop-openai (openai)\n\
             --title=coop-openai (openai)\n"
        );
    }

    #[test]
    fn parse_recognises_any_cat_txt_file() {
        // The file layout is now per-service (`<dir>/<account>.txt`), so any
        // `cat <dir>/<name>.txt` with a valid account stem is the File backend
        // — deletion recomputes the path from the state dir + service, so this
        // superset never causes coop to delete a file it did not write.
        assert_eq!(
            backend_of("cmd:cat ~/.coop/state/github-pat/x.txt"),
            Some(Backend::File)
        );
        assert_eq!(
            backend_of("cmd:cat ~/.coop/state/anthropic/anthropic.txt"),
            Some(Backend::File)
        );
        // A non-`.txt` suffix is still not a form coop writes.
        assert_eq!(
            backend_of("cmd:cat ~/.coop/state/github-pat/x.bin"),
            None,
            "non-.txt suffix must not match File"
        );
    }

    #[test]
    fn parse_strips_and_trims_cmd_prefix() {
        // `resolve_cmd_value` tolerates `cmd:` with leading space; parsing
        // must recover the same backend whether or not the space is present.
        assert_eq!(
            backend_of("cmd: op item get foo --fields password --reveal"),
            Some(Backend::OnePassword)
        );
    }

    #[test]
    fn store_outputs_round_trip_through_parse() {
        // The cmd string a backend actually writes must parse back to the
        // backend that wrote it — this is the divergence the type prevents.
        let tmp = tempfile::TempDir::new().unwrap();
        let acc = account("trailofbits/coop");
        let token = store_file(SERVICE, &acc, "github_pat_xyz", tmp.path()).unwrap();
